#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex regex(R"(<p>(.*?)</p>)");
    std::regex_replace(html, html, regex, "<p>$1</p>");
    return html;
}

int main() {
    std::string markdown = "This is a paragraph. This is another paragraph.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This function uses a regular expression to match HTML tags (`<p>`) and replaces them with the corresponding HTML tags. The regular expression `R"(<p>(.*?)</p>)"` matches any text between `<p>` and `</p>` tags, and the `std::regex_replace` function is used to replace these matches with `<p>$1</p>`, where `$1` is the text inside the `<p>` tags. The `main` function demonstrates how this function converts markdown formatted text and prints the resulting HTML formatted text.

